// =====================================================
// 万年仇怨境界控制助手 v6
// 功能：根据主角境界自动开启「万年仇怨」世界书条目
// 特点：普通条目只开启不关闭；五个进程互斥；进程只允许向上切换，不因降境界降级
// 说明：基于已验证可用的「蜀山扩展助手」框架修改
// =====================================================

(function () {
    'use strict';

    const p = window.parent || window;

    // ===============================
    // 世界书关键词
    // ===============================

    const WORLDBOOK_KEYWORD = "万年仇怨";

    // ===============================
    // 境界 → 世界书条目
    // ===============================

    const REALM_ENTRIES = {
        "筑基": [
            "天华帝国历史",
            "人物详情: 疯帝-瑕",
            "进程一: 萌动",
            "血肉机关生成",
            "血肉机关: 血傀"
        ],

        "金丹": [
            "进程二: 爆发",
            "血肉机关: 血巢"
        ],

        "元婴": [
            "进程三: 升华",
            "血肉机关: 毕方",
            "血肉机关: 相柳",
            "血肉机关: 蠃鱼",
            "血肉机关: 白泽",
            "疯嚣之作: 梼杌"
        ],

        "化神": [
            "进程三: 升华",
            "血肉机关: 毕方",
            "血肉机关: 相柳",
            "血肉机关: 蠃鱼",
            "血肉机关: 白泽",
            "疯嚣之作: 梼杌"
        ],

        "炼虚": [
            "进程四: 灾劫",
            "疯嚣之作: 穷奇",
            "疯嚣之作: 饕餮",
            "疯嚣之作: 混沌",
            "血肉机关: 共工",
            "血肉机关: 祝融"
        ],

        "合体": [
            "进程五: 疯嚣"
        ],

        "大乘": [
            "进程五: 疯嚣"
        ],

        "渡劫": [
            "进程五: 疯嚣"
        ]
    };

    // ===============================
    // 跨窗口执行
    // ===============================

    function runInParent(code) {
        return new Promise((resolve, reject) => {
            const token = "wy_" + Date.now() + Math.random();

            const handler = (e) => {
                if (!e.detail || e.detail.token !== token) return;

                p.document.removeEventListener("wy_result", handler);

                if (e.detail.error) {
                    reject(new Error(e.detail.error));
                } else {
                    resolve(e.detail.result);
                }
            };

            p.document.addEventListener("wy_result", handler);

            const script = p.document.createElement("script");

            script.textContent = `
            (async () => {
                try {
                    let result = await (${code});

                    document.dispatchEvent(
                        new CustomEvent("wy_result", {
                            detail: {
                                token: "${token}",
                                result
                            }
                        })
                    );

                } catch (e) {
                    document.dispatchEvent(
                        new CustomEvent("wy_result", {
                            detail: {
                                token: "${token}",
                                error: e.message
                            }
                        })
                    );
                }
            })();
            `;

            p.document.body.appendChild(script);
            script.remove();
        });
    }

    // ===============================
    // 读取 MVU
    // ===============================

    async function readStatData() {
        try {
            const stat = await runInParent(`
            (async () => {
                if (typeof TavernHelper === "undefined") {
                    throw new Error("TavernHelper 不存在");
                }

                const vars = await TavernHelper.getVariables();

                console.log(
                    "[万年仇怨助手] stat_data =",
                    vars.stat_data
                );

                return vars.stat_data || null;
            })()
            `);

            if (!stat) {
                console.warn(
                    "[万年仇怨助手] 没有读取到 stat_data"
                );
            }

            return stat;

        } catch (e) {
            console.error(
                "[万年仇怨助手] MVU读取失败",
                e
            );
            return null;
        }
    }

    // ===============================
    // 自动寻找世界书
    // ===============================

    async function getWorldbook() {
        return await runInParent(`
        (async () => {

            if (typeof TavernHelper === "undefined") {
                throw new Error("TavernHelper 不存在");
            }

            // 优先查当前角色绑定的世界书
            const books =
                await TavernHelper.getCharWorldbookNames("current");

            console.log(
                "[万年仇怨助手] 当前角色世界书:",
                books
            );

            if (Array.isArray(books)) {
                for (const b of books) {
                    if (String(b).includes(${JSON.stringify(WORLDBOOK_KEYWORD)})) {
                        return b;
                    }
                }
            }

            // 当前角色没找到，再查全部世界书
            const all =
                await TavernHelper.getWorldbookNames();

            console.log(
                "[万年仇怨助手] 全部世界书:",
                all
            );

            if (Array.isArray(all)) {
                for (const b of all) {
                    if (String(b).includes(${JSON.stringify(WORLDBOOK_KEYWORD)})) {
                        return b;
                    }
                }
            }

            return null;

        })()
        `);
    }

    // ===============================
    // 根据境界计算需要开启的条目
    // ===============================

    function getEnableList(stat) {
        const result = new Set();

        if (!stat) {
            console.warn(
                "[万年仇怨助手] stat_data 为空"
            );
            return {
                stageIndex: -1,
                entries: result
            };
        }

        const main = stat.主角 || {};
        const realm = String(main.境界 || "").trim();

        console.log(
            "[万年仇怨助手] 主角数据:",
            main
        );

        console.log(
            "[万年仇怨助手] 当前境界:",
            realm
        );

        if (!realm) {
            console.warn(
                "[万年仇怨助手] 未读取到主角境界"
            );
            return {
                stageIndex: -1,
                entries: result
            };
        }

        // 境界递进：
        // 筑基 → 金丹 → 元婴 → 化神 → 炼虚 → 合体 → 大乘 → 渡劫
        //
        // 渡劫与大乘、合体共用进程五：疯嚣。

        const stages = [
            "筑基",
            "金丹",
            "元婴",
            "化神",
            "炼虚",
            "合体",
            "大乘",
            "渡劫"
        ];

        let stageIndex = -1;

        // 从最高境界向下匹配
        for (let i = stages.length - 1; i >= 0; i--) {
            if (realm.includes(stages[i])) {
                stageIndex = i;
                break;
            }
        }

        if (stageIndex < 0) {
            console.warn(
                "[万年仇怨助手] 当前境界未达到控制范围:",
                realm
            );
            return {
                stageIndex: -1,
                entries: result
            };
        }

        // 这里只计算“当前境界向上提升时需要补开的普通条目”。
        // 是否实际开启，由 apply() 根据世界书当前进程状态决定。
        //
        // 这样可以保证：
        // 1. 直接高境界开局时，会补齐前置普通条目；
        // 2. 境界下降时，不会因为低境界重新计算而把原本关闭的内容打开。
        const processNames = new Set([
            "进程一: 萌动",
            "进程二: 爆发",
            "进程三: 升华",
            "进程四: 灾劫",
            "进程五: 疯嚣"
        ]);

        for (let i = 0; i <= stageIndex; i++) {
            const stage = stages[i];
            if (!REALM_ENTRIES[stage]) continue;

            REALM_ENTRIES[stage].forEach(entry => {
                if (!processNames.has(entry)) {
                    result.add(entry);
                }
            });
        }

        console.log(
            "[万年仇怨助手] 境界匹配:",
            realm,
            "→ 阶段序号:",
            stageIndex,
            "→ 普通条目候选:",
            [...result]
        );

        return {
            stageIndex,
            entries: result
        };
    }

    // ===============================
    // 应用世界书
    // ===============================

    async function apply(plan) {
        if (!plan || plan.stageIndex < 0) {
            console.log(
                "[万年仇怨助手] 没有有效的境界计划"
            );
            return;
        }

        const entriesToEnable = plan.entries;

        // 自动寻找世界书
        const wb = await getWorldbook();

        if (!wb) {
            console.error(
                "[万年仇怨助手] 找不到包含「" +
                WORLDBOOK_KEYWORD +
                "」的世界书"
            );
            return;
        }

        console.log(
            "[万年仇怨助手] 使用世界书:",
            wb
        );

        await runInParent(`
        (async () => {

            const worldbookName = ${JSON.stringify(wb)};
            const targetStageIndex = ${JSON.stringify(plan.stageIndex)};

            const book =
                await TavernHelper.getWorldbook(
                    worldbookName
                );

            if (!Array.isArray(book)) {
                throw new Error(
                    "读取世界书失败: " + worldbookName
                );
            }

            console.log(
                "[万年仇怨助手] 世界书条目数量:",
                book.length
            );

            const processNames = [
                "进程一: 萌动",
                "进程二: 爆发",
                "进程三: 升华",
                "进程四: 灾劫",
                "进程五: 疯嚣"
            ];

            // 进程对应的阶段：
            // 进程一 = 筑基
            // 进程二 = 金丹
            // 进程三 = 元婴/化神
            // 进程四 = 炼虚
            // 进程五 = 合体/大乘/渡劫
            const processStageIndex = {
                "进程一: 萌动": 0,
                "进程二: 爆发": 1,
                "进程三: 升华": 2,
                "进程四: 灾劫": 4,
                "进程五: 疯嚣": 5
            };

            // 读取世界书当前实际开启的进程。
            // 正常情况下只能有一个；如果发现多个，取最高的一个作为
            // “已经达到过的最高进程”，但不会在这里主动关闭其他进程。
            // 这样脚本本身不会因为降境界而制造关闭动作。
            let currentProcess = null;
            let currentProcessStage = -1;

            for (const e of book) {
                const name =
                    e.comment ||
                    e.name ||
                    "";

                if (
                    processNames.includes(name) &&
                    e.enabled === true
                ) {
                    const stage = processStageIndex[name];

                    if (stage > currentProcessStage) {
                        currentProcess = name;
                        currentProcessStage = stage;
                    }
                }
            }

            // 根据当前境界找到应该达到的进程。
            let targetProcess = null;

            if (targetStageIndex >= 5) {
                targetProcess = "进程五: 疯嚣";
            } else if (targetStageIndex >= 4) {
                targetProcess = "进程四: 灾劫";
            } else if (targetStageIndex >= 2) {
                targetProcess = "进程三: 升华";
            } else if (targetStageIndex >= 1) {
                targetProcess = "进程二: 爆发";
            } else if (targetStageIndex >= 0) {
                targetProcess = "进程一: 萌动";
            }

            console.log(
                "[万年仇怨助手] 当前已开启进程:",
                currentProcess,
                "→ 当前进程阶段:",
                currentProcessStage,
                "→ 当前境界目标进程:",
                targetProcess
            );

            let changed = false;
            const found = new Set();
            const enabledNow = [];

            // =====================================================
            // 进程规则：
            // 1. 没有任何进程开启：开启当前境界对应进程。
            // 2. 当前境界高于已经开启的进程：切换到更高进程。
            // 3. 当前境界等于或低于已经开启的进程：保持原进程，不降级。
            // 4. 进程始终保持互斥：升级时只关闭旧进程、开启新进程。
            // =====================================================

            let processToEnable = currentProcess;

            if (currentProcess === null) {
                processToEnable = targetProcess;
            } else {
                const targetStage =
                    processStageIndex[targetProcess];

                if (targetStage > currentProcessStage) {
                    processToEnable = targetProcess;
                }
            }

            for (const e of book) {

                const name =
                    e.comment ||
                    e.name ||
                    "";

                if (processNames.includes(name)) {
                    found.add(name);

                    if (name === processToEnable) {
                        if (e.enabled !== true) {
                            e.enabled = true;
                            changed = true;
                            enabledNow.push(name);
                        }
                    } else if (
                        processToEnable !== currentProcess &&
                        e.enabled === true
                    ) {
                        // 只有发生“向更高进程升级”时才关闭旧进程。
                        // 降境界绝不会触发这里。
                        e.enabled = false;
                        changed = true;
                    }

                    continue;
                }

                // =====================================================
                // 普通条目：
                // 只开启，不关闭。
                //
                // 升境界或直接高境界开局时，补齐当前阶段以前的普通条目。
                // 降境界时，已经达到过更高进程后，不会因为低境界重新
                // 计算而关闭任何条目，也不会触发进程降级。
                // =====================================================
                if (entriesToEnable.has(name)) {

                    found.add(name);

                    // 如果当前境界低于已经达到过的最高进程，
                    // 说明这是一次降境界检查：
                    // 不主动重新开启原本关闭的普通条目。
                    const isDowngrade =
                        currentProcessStage >= 0 &&
                        targetStageIndex < currentProcessStage;

                    if (
                        !isDowngrade &&
                        e.enabled !== true
                    ) {
                        e.enabled = true;
                        changed = true;
                        enabledNow.push(name);
                    }
                }
            }

            const missing = [...entriesToEnable].filter(
                x => !found.has(x)
            );

            if (missing.length > 0) {
                console.warn(
                    "[万年仇怨助手] 世界书中找不到这些条目:",
                    missing
                );
            }

            if (changed) {

                await TavernHelper.replaceWorldbook(
                    worldbookName,
                    book
                );

                console.log(
                    "[万年仇怨助手] 本次开启:",
                    enabledNow
                );

            } else {

                console.log(
                    "[万年仇怨助手] 当前状态无需修改"
                );
            }

            return true;

        })()
        `);
    }

    // ===============================
    // 主执行
    // ===============================

    async function run() {
        try {
            console.log(
                "[万年仇怨助手] ===== 开始检查 ====="
            );

            const stat =
                await readStatData();

            const enable =
                getEnableList(stat);

            await apply(enable);

            console.log(
                "[万年仇怨助手] ===== 检查结束 ====="
            );

        } catch (e) {

            console.error(
                "[万年仇怨助手] 执行失败:",
                e
            );
        }
    }

    // ===============================
    // 启动
    // ===============================

    setTimeout(
        run,
        1000
    );

    // 暴露手动测试
    window.runWanNianHelper = run;

    console.log(
        "[万年仇怨境界控制助手 v6] 已加载"
    );

})();
